export class AdversarialTestingModule {
  constructor() {
    this.edgeCases = [];
  }

  generateEdgeCase(input) {
    const edgeCase = { ...input, adversarial: true };
    this.edgeCases.push(edgeCase);
    return edgeCase;
  }

  testResponse(response, expected) {
    const isRobust = response === expected;
    console.log(`Response robustness: ${isRobust}`);
    return isRobust;
  }
}

// Example usage
const atm = new AdversarialTestingModule();
const edgeCase = atm.generateEdgeCase({ input: 'test' });
atm.testResponse('output', 'expected');